import functools
import asyncio
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

def dep(q: str):
    return q

partial_dep = functools.partial(dep, q="foo")

@app.get("/test-partial")
async def read_items(val: str = Depends(partial_dep)):
    return {"val": val}

async def async_dep(q: str):
    return q

partial_async_dep = functools.partial(async_dep, q="foo")

@app.get("/test-partial-async")
async def read_async_items(val: str = Depends(partial_async_dep)):
    return {"val": val}

class DepClass:
    def __call__(self, q: str):
        return q

dep_class = DepClass()
partial_class_dep = functools.partial(dep_class, q="foo")

@app.get("/test-partial-class")
async def read_class_items(val: str = Depends(partial_class_dep)):
    return {"val": val}

client = TestClient(app)

def test_partial():
    response = client.get("/test-partial")
    print(f"Partial: {response.json()}")
    assert response.status_code == 200

def test_partial_async():
    response = client.get("/test-partial-async")
    print(f"Partial Async: {response.json()}")
    assert response.status_code == 200

def test_partial_class():
    response = client.get("/test-partial-class")
    print(f"Partial Class: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    test_partial()
    test_partial_async()
    test_partial_class()
    print("All tests passed!")
", "filepath": "/workspace/repro_app.py"}

